-- Restore of a Fotocopias UPB backup (story #51), made on {{CREATED_AT}} (UTC) at migration {{MIGRATION}}.
-- Generated by scripts/restore-sql.ts; steps in docs/maintenance.md, "Restore a backup".
-- It holds the PIN hashes: never commit it, and delete it (and this query) after the restore.
--
-- Replaces EVERY row of every table except admins with the rows of the file. Check the project name
-- at the top of the dashboard before clicking Run. The database must be at migration {{MIGRATION}}:
-- if its tables or columns differ from the file's, the script stops before changing anything.
-- One transaction: the first failed check stops the script and nothing is changed. Success = the last
-- result lists every table with the same number of rows in the file and in the database.

begin;

create temp table restore_file on commit drop as
select {{BACKUP}}::jsonb as backup;

-- The tables a backup holds (as in backup_data(), 0024): every table in public but admins, without
-- generated columns.
create temp table restore_tables on commit drop as
select c.oid::regclass as tbl,
       c.relname::text as name,
       (select string_agg(quote_ident(a.attname), ', ' order by a.attnum)
        from pg_attribute a
        where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
       ) as cols,
       (select array_agg(a.attname::text order by a.attname::text)
        from pg_attribute a
        where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
       ) as col_names,
       (select a.attname::text
        from pg_attribute a
        where a.attrelid = c.oid and a.attidentity <> ''
       ) as identity_col
from pg_class c
where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname <> 'admins';

create temp table restore_report (name text, rows_in_file integer, rows_restored integer) on commit drop;

do $$
declare
  b jsonb := (select backup from restore_file);
  t record;
  differ text;
  bad integer;
  todo regclass[] := array(select tbl from restore_tables);
  next_table regclass;
  max_id bigint;
  diff integer;
begin
  -- Same tables in the file and in the database.
  select string_agg(coalesce(f.name, d.name) || case when d.name is null then ' (only in the file)'
                                                     else ' (only in the database)' end, ', ')
  into differ
  from (select k as name from jsonb_object_keys(b -> 'tables') k) f
  full join restore_tables d on d.name = f.name
  where f.name is null or d.name is null;
  if differ is not null then
    raise exception 'Tables differ: %. This file needs a database at migration %.', differ, b ->> 'migration';
  end if;

  -- Same columns: jsonb_populate_recordset would silently drop unknown keys and leave missing
  -- columns null, so every row must have exactly the table's columns.
  for t in select * from restore_tables order by name loop
    select count(*) into bad
    from jsonb_array_elements(b -> 'tables' -> t.name) r
    where (select array_agg(k order by k) from jsonb_object_keys(r) k) is distinct from t.col_names;
    if bad > 0 then
      raise exception '%: % rows have other columns than the database (%). This file needs a database at migration %.',
                      t.name, bad, array_to_string(t.col_names, ', '), b ->> 'migration';
    end if;
  end loop;

  -- Empty every table (the lists seeded by the migrations too), numbering from 1 again.
  execute (select 'truncate ' || string_agg(tbl::text, ', ') || ' restart identity' from restore_tables);

  -- Insert parents before children: next is a table whose foreign keys point only to tables already
  -- filled (or outside the backup, or to itself).
  while cardinality(todo) > 0 loop
    select tbl into next_table
    from unnest(todo) tbl
    where not exists (select from pg_constraint fk
                      where fk.contype = 'f' and fk.conrelid = tbl::oid and fk.confrelid <> tbl::oid
                        and fk.confrelid = any (todo::oid[]))
    order by tbl::text
    limit 1;
    if next_table is null then
      raise exception 'Circular foreign keys between: %', todo;
    end if;

    select * into t from restore_tables where tbl = next_table;
    -- overriding system value keeps the ids of "generated always" identity columns.
    execute format('insert into %s (%s) %s select %s from jsonb_populate_recordset(null::%s, $1)',
                   t.tbl, t.cols, case when t.identity_col is not null then 'overriding system value' else '' end,
                   t.cols, t.tbl)
      using b -> 'tables' -> t.name;
    todo := array_remove(todo, next_table);
  end loop;

  -- The next new row continues after the highest id restored.
  for t in select * from restore_tables where identity_col is not null loop
    execute format('select max(%I) from %s', t.identity_col, t.tbl) into max_id;
    if max_id is not null then
      perform setval(pg_get_serial_sequence(t.tbl::text, t.identity_col), max_id);
    end if;
  end loop;

  -- Each table must equal the file exactly: nothing missing, nothing extra, every value the same
  -- (the same check as supabase/tests/backups.sql).
  for t in select * from restore_tables order by name loop
    execute format(
      'select (select count(*) from (select %1$s from %2$s except all
                                     select %1$s from jsonb_populate_recordset(null::%2$s, $1)) x)
            + (select count(*) from (select %1$s from jsonb_populate_recordset(null::%2$s, $1) except all
                                     select %1$s from %2$s) y)', t.cols, t.tbl)
      using b -> 'tables' -> t.name
      into diff;
    if diff <> 0 then
      raise exception '%: % rows differ between the table and the file', t.name, diff;
    end if;

    execute format('insert into restore_report select %L, %s, (select count(*) from %s)',
                   t.name, jsonb_array_length(b -> 'tables' -> t.name), t.tbl);
  end loop;
end $$;

-- Run the deferred checks (sizes and departments valid on each date, 0020 and 0021) now, so a
-- failure shows here instead of the report below.
set constraints all immediate;

select name as "table", rows_in_file, rows_restored from restore_report order by name;

commit;
